-- выполнено владельцем схемы sales
GRANT SELECT ON sales.orders TO bob;

-- выполняет bob
SELECT * FROM sales.orders;

CREATE ROLE readers NOLOGIN;
GRANT SELECT ON orders TO readers;

CREATE ROLE ann LOGIN INHERIT;
CREATE ROLE bob LOGIN NOINHERIT;
GRANT readers TO ann, bob;

ALTER TABLE docs ENABLE ROW LEVEL SECURITY;
-- политик на таблице нет
GRANT SELECT ON docs TO app;

-- владелец таблицы orders и представления v_orders — роль admin
CREATE VIEW v_orders AS
  SELECT id, amount FROM orders;
GRANT SELECT ON v_orders TO reporter;

-- выполняет reporter, у которого нет прав на orders
SELECT * FROM v_orders;

CREATE FUNCTION find_user(p_name text)
RETURNS SETOF users LANGUAGE plpgsql AS $$
BEGIN
  RETURN QUERY EXECUTE
    'SELECT * FROM users WHERE name = ''' || p_name || '''';
END $$;

-- приложение вызывает функцию с параметром:
-- SELECT * FROM find_user($1);

-- выполняет admin
ALTER DEFAULT PRIVILEGES IN SCHEMA app
  GRANT SELECT ON TABLES TO reader;

-- позже выполняет роль migrator (не admin)
CREATE TABLE app.invoices (id int);

ALTER TABLE docs ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON docs
  FOR ALL TO app
  USING (tenant_id = current_setting('app.tenant_id')::int);

PREPARE list_users(text) AS
  SELECT id, name, created_at FROM users ORDER BY $1;

EXECUTE list_users('created_at');

